 * Generates a print-only stylesheet.
 *
 * The returned CSS consists of exactly two top-level constructs:
 *   1. an `@page` rule setting the page margins
 *   2. a single `@media print` block with all style rules
 *
 * Nothing leaks outside the print media context.
 *
 * @param {object} [options]
 * @param {string[]} [options.hide]        Selectors to hide in print (display: none).
 * @param {string}   [options.margin]      Page margin for the @page rule. Default "1.5cm".
 * @param {string[]} [options.noBreak]     Extra selectors that must not split across pages.
 * @returns {string} The generated CSS.
 */
export function printStyles(options = {}) {
  const {
    hide = [],
    margin = "1.5cm",
    noBreak = [],
  } = options;

  const rules = [];

  // Force a clean canvas: white background, black text.
  rules.push([
    "html, body",
    [
      ["background", "#fff"],
      ["color", "#000"],
    ],
  ]);

  // Hide configured elements.
  if (hide.length > 0) {
    rules.push([
      hide.join(",\n"),
      [
        ["display", "none"],
      ],
    ]);
  }

  // Append the target URL after external links when printed.
  rules.push([
    'a[href^="http"]:after',
    [
      ["content", '" (" attr(href) ")'],
    ],
  ]);

  // Avoid splitting code blocks and tables across page breaks.
  const noBreakSelectors = ["pre", "table", ...noBreak];
  rules.push([
    noBreakSelectors.join(",\n"),
    [
      ["break-inside", "avoid"],
    ],
  ]);

  const body = rules
    .map(([selector, decls]) => {
      const declarations = decls
        .map(([prop, value]) => `  ${prop}: ${value};`)
        .join("\n");
      return `${selector} {\n${declarations}\n}`;
    })
    .join("\n\n");

  return `@media print {\n${body}\n}\n\n@page {\n  margin: ${margin};\n}\n`;
}

export default printStyles;
"})
