import postcss from "postcss";
import { printStyles } from "../src/print.js";

/** Parse generated CSS and collect every Rule node together with its ancestors. */
function analyze(css) {
  const root = postcss.parse(css);
  const rules = [];
  const medias = [];
  const pages = [];

  root.walk((node) => {
    if (node.type === "atrule" && node.name === "media") {
      medias.push(node);
      node.walkRules((rule) => rules.push({ rule, media: node }));
    } else if (node.type === "atrule" && node.name === "page") {
      pages.push(node);
    }
  });

  // Any rule NOT discovered inside a @media print block:
  const strayRules = [];
  root.walkRules((rule) => {
    if (!rules.some((r) => r.rule === rule)) strayRules.push(rule);
  });

  return { root, rules, medias, pages, strayRules };
}

describe("printStyles", () => {
  it("returns only a print block and a page rule", () => {
    const css = printStyles({ hide: [".ads", "nav"] });

    // Top level must contain exactly one @media and one @page at-rule, nothing else.
    const topLevel = css
      .split("}")
      .map((s) => s.trim())
      .filter(Boolean);
    expect(topLevel.length).toBeGreaterThanOrEqual(2);

    const { root, medias, pages, strayRules } = analyze(css);
    expect(root.nodes.filter((n) => n.type === "rule")).toHaveLength(0);
    expect(medias).toHaveLength(1);
    expect(medias[0].params.replace(/\s/g, "")).toBe("print");
    expect(pages).toHaveLength(1);
    expect(strayRules).toHaveLength(0);
  });

  it("places every style rule under media print", () => {
    const css = printStyles({
      hide: [".sidebar", "#cookie-banner", "nav", "footer"],
    });
    const { rules } = analyze(css);

    expect(rules.length).toBeGreaterThan(0);
    for (const { media } of rules) {
      expect(media.name).toBe("print");
    }
  });

  it("forces white backgrounds and black text", () => {
    const { rules } = analyze(printStyles());
    const bodyRule = rules.find((r) =>
      /(^|,\s*)body(\s*,|$)/.test(r.rule.selector),
    );
    expect(bodyRule).toBeDefined();
    expect(bodyRule.rule.propOf?.call || true).toBeTruthy();
    const decls = Object.fromEntries(
      bodyRule.rule.nodes.map((d) => [d.prop, d.value]),
    );
    expect(decls["background"]).toMatch(/#fff|white/i);
    expect(decls["color"]).toMatch(/#000|black/i);
  });

  it('appends attr(href) after external links via a[href^="http"]:after', () => {
    const { rules } = analyze(printStyles());
    const linkRule = rules.find((r) =>
      r.rule.selector.includes('a[href^="http"]:after'),
    );
    expect(linkRule).toBeDefined();

    const contentDecl = linkRule.rule.nodes.find((d) => d.prop === "content");
    expect(contentDecl).toBeDefined();
    expect(contentDecl.value).toContain("attr(href)");
    // href appears inside quotes in the emitted declaration value
    expect(linkRule.rule.toString()).toMatch(/content\s*:\s*["'].*attr\(href\).*["']/);
  });

  it("avoids page breaks inside pre and table via break-inside: avoid", () => {
    const { rules } = analyze(printStyles());
    const noBreak = rules.find((r) => /(^|,)pre(\s*,|$)|\btable\b/.test(r.rule.selector));
    expect(noBreak).toBeDefined();

    const decl = noBreak.rule.nodes.find((d) => d.prop === "break-inside");
    expect(decl).toBeDefined();
    expect(decl.value.trim()).toBe("avoid");
  });

  it("emits an @page rule with a sensible margin", () => {
    const { pages } = analyze(printStyles());
    expect(pages).toHaveLength(1);

    const margin = pages[0].nodes.find((d) => d.prop === "margin");
    expect(margin).toBeDefined();
    expect(margin.value).toMatch(/^\d+(\.\d+)?(cm|mm|in)$/);
  });

  it.each([
    [[".ads"]],
    [[], ".fallback"],
  ])("hides configured selectors with display none (%#)", (hide) => {
    const selectors = [".sidebar", "#cookie-banner"];
    const hideArg = hide.length ? hide : undefined;
    void hideArg;

    const css = printStyles({
      hide: [...hide, ...selectors],
    });
    const { rules } = analyze(css);

    for (const selector of [...hide, ...selectors]) {
      const rule = rules.find((r) =>
        r.rule.selector.split(",").map((s) => s.trim()).includes(selector),
      );
      expect(rule, `missing rule for ${selector}`).toBeDefined();
      expect(rule.media.name).toBe("print");

      const decl = rule.rule.nodes.find((d) => d.prop === "display");
      expect(decl, `${selector} missing display declaration`).toBeDefined();
      expect(decl.value.trim()).toBe("none");
    }
  });
});
"})
